begin;
alter table public.beer_profiles add column friend_code text not null default upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)), add column selected_tag text;
create unique index beer_profiles_friend_code on public.beer_profiles(friend_code);
create policy profiles_members on public.beer_profiles for select to authenticated using(true);

create table public.beer_preferences (
 user_id uuid primary key default auth.uid() references auth.users(id) on delete cascade,
 home_city text not null default '' check(char_length(home_city)<=80)
);
alter table public.beer_preferences enable row level security;
revoke all on public.beer_preferences from public,anon,authenticated;
grant select,insert,update on public.beer_preferences to authenticated;
create policy preferences_read on public.beer_preferences for select to authenticated using(user_id=(select auth.uid()));
create policy preferences_insert on public.beer_preferences for insert to authenticated with check(user_id=(select auth.uid()));
create policy preferences_update on public.beer_preferences for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));

create table public.beer_friendships (
 id uuid primary key default gen_random_uuid(), requester uuid not null default auth.uid() references public.beer_profiles(user_id) on delete cascade,
 recipient uuid not null references public.beer_profiles(user_id) on delete cascade,
 status text not null default 'pending' check(status in ('pending','accepted')), created_at timestamptz not null default now(),check(requester<>recipient)
);
create unique index friendships_pair on public.beer_friendships(least(requester,recipient),greatest(requester,recipient));
create index friendships_recipient on public.beer_friendships(recipient,status);
create index friendships_requester on public.beer_friendships(requester,status);
alter table public.beer_friendships enable row level security;
revoke all on public.beer_friendships from public,anon,authenticated;
grant select,insert,delete on public.beer_friendships to authenticated;
grant update(status) on public.beer_friendships to authenticated;
create policy friends_read on public.beer_friendships for select to authenticated using((select auth.uid()) in (requester,recipient));
create policy friends_request on public.beer_friendships for insert to authenticated with check(requester=(select auth.uid()) and status='pending');
create policy friends_accept on public.beer_friendships for update to authenticated using(recipient=(select auth.uid()) and status='pending') with check(recipient=(select auth.uid()) and status='accepted');
create policy friends_remove on public.beer_friendships for delete to authenticated using((select auth.uid()) in (requester,recipient));

create table public.beer_follows (
 user_id uuid not null default auth.uid() references public.beer_profiles(user_id) on delete cascade,
 target_id uuid not null references public.beer_profiles(user_id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,target_id),check(user_id<>target_id)
);
create index follows_target on public.beer_follows(target_id);
alter table public.beer_follows enable row level security;
revoke all on public.beer_follows from public,anon,authenticated;
grant select,insert,delete on public.beer_follows to authenticated;
create policy follows_read on public.beer_follows for select to authenticated using((select auth.uid()) in(user_id,target_id));
create policy follows_add on public.beer_follows for insert to authenticated with check(user_id=(select auth.uid()));
create policy follows_remove on public.beer_follows for delete to authenticated using(user_id=(select auth.uid()));

create table public.beer_presence (
 user_id uuid primary key default auth.uid() references public.beer_profiles(user_id) on delete cascade,
 place_name text not null check(char_length(trim(place_name)) between 1 and 120),place_city text not null check(char_length(trim(place_city)) between 1 and 80),
 expires_at timestamptz not null default now()+interval '2 hours' check(expires_at<=now()+interval '4 hours'),created_at timestamptz not null default now()
);
create index presence_expiry on public.beer_presence(expires_at);
alter table public.beer_presence enable row level security;
revoke all on public.beer_presence from public,anon,authenticated;
grant select,insert,update,delete on public.beer_presence to authenticated;
create policy presence_read on public.beer_presence for select to authenticated using(user_id=(select auth.uid()) or (expires_at>now() and exists(select 1 from public.beer_friendships f where f.status='accepted' and ((f.requester=(select auth.uid()) and f.recipient=beer_presence.user_id) or (f.recipient=(select auth.uid()) and f.requester=beer_presence.user_id)))));
create policy presence_add on public.beer_presence for insert to authenticated with check(user_id=(select auth.uid()));
create policy presence_update on public.beer_presence for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy presence_remove on public.beer_presence for delete to authenticated using(user_id=(select auth.uid()));

create table public.beer_meetups (
 id uuid primary key default gen_random_uuid(),host_id uuid not null default auth.uid() references public.beer_profiles(user_id) on delete cascade,
 title text not null default 'Dnes na pivo?' check(char_length(trim(title)) between 1 and 100),note text not null default '' check(char_length(note)<=500),
 starts_at timestamptz not null check(starts_at>='2026-01-01'::timestamptz),place_name text not null check(char_length(trim(place_name)) between 1 and 120),place_city text not null check(char_length(trim(place_city)) between 1 and 80),
 visibility text not null default 'public' check(visibility in ('public','friends','private')), invited_id uuid references public.beer_profiles(user_id) on delete cascade,
 created_at timestamptz not null default now(),check((visibility='private' and invited_id is not null and invited_id<>host_id) or (visibility<>'private' and invited_id is null))
);
create index meetups_date on public.beer_meetups(starts_at desc,id);
create index meetups_host on public.beer_meetups(host_id);
create index meetups_invitee on public.beer_meetups(invited_id) where invited_id is not null;
alter table public.beer_meetups enable row level security;
revoke all on public.beer_meetups from public,anon,authenticated;
grant select on public.beer_meetups to anon,authenticated;
grant insert,delete on public.beer_meetups to authenticated;
create policy meetups_public_read on public.beer_meetups for select to anon,authenticated using(visibility='public');
create policy meetups_read on public.beer_meetups for select to authenticated using(host_id=(select auth.uid()) or invited_id=(select auth.uid()) or (visibility='friends' and exists(select 1 from public.beer_friendships f where f.status='accepted' and ((f.requester=(select auth.uid()) and f.recipient=host_id) or (f.recipient=(select auth.uid()) and f.requester=host_id)))));
create policy meetups_add on public.beer_meetups for insert to authenticated with check(host_id=(select auth.uid()) and starts_at>now()-interval '5 minutes' and starts_at<now()+interval '1 year' and (invited_id is null or exists(select 1 from public.beer_friendships f where f.status='accepted' and ((f.requester=(select auth.uid()) and f.recipient=invited_id) or (f.recipient=(select auth.uid()) and f.requester=invited_id)))));
create policy meetups_remove on public.beer_meetups for delete to authenticated using(host_id=(select auth.uid()));
create table public.beer_rsvps (meetup_id uuid not null references public.beer_meetups(id) on delete cascade,user_id uuid not null default auth.uid() references public.beer_profiles(user_id) on delete cascade,created_at timestamptz not null default now(),primary key(meetup_id,user_id));
create index rsvps_user on public.beer_rsvps(user_id);
alter table public.beer_rsvps enable row level security;
revoke all on public.beer_rsvps from public,anon,authenticated;
grant select,insert,delete on public.beer_rsvps to authenticated;
create policy rsvps_read on public.beer_rsvps for select to authenticated using(exists(select 1 from public.beer_meetups m where m.id=meetup_id));
create policy rsvps_add on public.beer_rsvps for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.beer_meetups m where m.id=meetup_id and m.starts_at>now()-interval '4 hours'));
create policy rsvps_remove on public.beer_rsvps for delete to authenticated using(user_id=(select auth.uid()));

alter table public.beer_entries add column photo_path text;
alter table public.beer_entries add constraint photo_owner_path check(photo_path is null or photo_path=user_id::text||'/'||id::text||'.jpg');
grant update(photo_path) on public.beer_entries to authenticated;
create or replace view public.beer_feed with(security_invoker=true) as
 select e.id,e.user_id,e.catalog_id,e.beer,e.brewery,e.style,e.volume,e.count,e.date,e.rating,e.note,e.place_name,e.place_city,e.created_at,
 coalesce(p.nickname,'Pivní objevitel') as nickname,
 (select count(*) from public.beer_cheers c where c.entry_id=e.id) as cheers_count,
 exists(select 1 from public.beer_cheers c where c.entry_id=e.id and c.user_id=(select auth.uid())) as cheered,e.photo_path,p.selected_tag,p.friend_code
 from public.beer_entries e left join public.beer_profiles p on p.user_id=e.user_id where e.is_public;

create table public.beer_badge_definitions (
 id text primary key,metric text not null,target integer not null check(target>0),tag text,definition jsonb not null
);
alter table public.beer_badge_definitions enable row level security;
revoke all on public.beer_badge_definitions from public,anon,authenticated;
grant select on public.beer_badge_definitions to anon,authenticated;
create policy badges_read on public.beer_badge_definitions for select to anon,authenticated using(true);
create table public.beer_achievements (
 user_id uuid not null references auth.users(id) on delete cascade,badge_id text not null references public.beer_badge_definitions(id),awarded_at timestamptz not null default now(),primary key(user_id,badge_id)
);
alter table public.beer_achievements enable row level security;
revoke all on public.beer_achievements from public,anon,authenticated;
grant select on public.beer_achievements to authenticated;
create policy achievements_own on public.beer_achievements for select to authenticated using(user_id=(select auth.uid()));

create function private.guard_beer_profile() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='UPDATE' and new.friend_code<>old.friend_code then raise exception 'Friend code is immutable' using errcode='42501';end if;
 if tg_op='INSERT' then new.friend_code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));end if;
 if new.selected_tag is not null and not exists(select 1 from public.beer_achievements a join public.beer_badge_definitions d on d.id=a.badge_id where a.user_id=new.user_id and d.tag=new.selected_tag) then raise exception 'Tag has not been earned' using errcode='42501';end if;
 return new;
end $$;
revoke all on function private.guard_beer_profile() from public,anon,authenticated;
create trigger guard_beer_profile before insert or update on public.beer_profiles for each row execute function private.guard_beer_profile();

create function private.sync_beer_achievements() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); facts jsonb; new_ids jsonb; awards jsonb;
begin
 if uid is null then raise exception 'Sign in required' using errcode='42501';end if;
 select jsonb_build_object(
 'beers',count(distinct catalog_id),'breweries',count(distinct lower(trim(brewery))), 'styles',count(distinct style),
 'places',count(distinct lower(trim(place_name))||chr(9)||lower(trim(place_city))) filter(where trim(place_name)<>''),
 'cities',count(distinct lower(trim(place_city))) filter(where trim(place_city)<>''),
 'rated',count(distinct catalog_id) filter(where rating>0),'notes',count(distinct catalog_id) filter(where trim(note)<>''),
 'photos',count(distinct catalog_id) filter(where photo_path is not null and exists(select 1 from storage.objects o where o.bucket_id='beer-photos' and o.name=e.photo_path)),'days',count(distinct date),'months',count(distinct extract(month from date)),
 'nonalc',count(distinct catalog_id) filter(where style='Nealkoholické'),'publicdays',count(distinct date) filter(where is_public),
 'spring',count(distinct date) filter(where extract(month from date) in(3,4,5)), 'summer',count(distinct date) filter(where extract(month from date) in(6,7,8)),
 'autumn',count(distinct date) filter(where extract(month from date) in(9,10,11)), 'winter',count(distinct date) filter(where extract(month from date) in(12,1,2)),
 'style_lager',count(distinct catalog_id) filter(where style='Ležák'),'style_ipa',count(distinct catalog_id) filter(where style='IPA'),
 'style_pale',count(distinct catalog_id) filter(where style='Pale Ale'),'style_wheat',count(distinct catalog_id) filter(where style='Pšeničné'),
 'style_dark',count(distinct catalog_id) filter(where style='Stout / Porter'),'style_zero',count(distinct catalog_id) filter(where style='Nealkoholické'),
 'style_other',count(distinct catalog_id) filter(where style='Jiné'),'total',coalesce(sum(count),0), 'litres',coalesce(sum(count*volume),0)
 ) into facts from public.beer_entries e where user_id=uid;
 facts:=facts||jsonb_build_object(
 'classic',coalesce((select max(n) from(select count(distinct date) n from public.beer_entries where user_id=uid group by catalog_id) s),0),
 'homebase',coalesce((select max(n) from(select count(distinct date) n from public.beer_entries where user_id=uid and trim(place_name)<>'' group by lower(trim(place_name)),lower(trim(place_city))) s),0),
 'wishes',(select count(*) from public.beer_wishlist where user_id=uid),
 'friends',(select count(*) from public.beer_friendships where status='accepted' and uid in(requester,recipient)),
 'hosted',(select count(distinct (created_at at time zone 'Europe/Prague')::date) from public.beer_meetups where host_id=uid),
 'rsvps',(select count(*) from public.beer_rsvps where user_id=uid));
 with fresh as(insert into public.beer_achievements(user_id,badge_id) select uid,d.id from public.beer_badge_definitions d where coalesce((facts->>d.metric)::numeric,0)>=d.target on conflict do nothing returning badge_id)
 select coalesce(jsonb_agg(badge_id),'[]'::jsonb) into new_ids from fresh;
 select coalesce(jsonb_agg(jsonb_build_object('badge_id',badge_id,'awarded_at',awarded_at) order by awarded_at,badge_id),'[]'::jsonb) into awards from public.beer_achievements where user_id=uid;
 return jsonb_build_object('facts',facts,'awards',awards,'new',new_ids);
end $$;
revoke all on function private.sync_beer_achievements() from public,anon,authenticated;
grant usage on schema private to authenticated;
grant execute on function private.sync_beer_achievements() to authenticated;
create function public.sync_beer_achievements() returns jsonb language sql security invoker set search_path='' as $$select private.sync_beer_achievements()$$;
revoke all on function public.sync_beer_achievements() from public,anon;
grant execute on function public.sync_beer_achievements() to authenticated;
create policy profiles_public_hosts on public.beer_profiles for select to anon using(exists(select 1 from public.beer_meetups m where m.host_id=beer_profiles.user_id and m.visibility='public'));

-- Photos stay in a private bucket; readers receive short-lived signed URLs.
create policy beer_photo_insert on storage.objects for insert to authenticated with check(bucket_id='beer-photos' and split_part(name,'/',1)=(select auth.uid())::text and name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.jpg$');
create policy beer_photo_read on storage.objects for select to anon,authenticated using(bucket_id='beer-photos' and (split_part(name,'/',1)=(select auth.uid())::text or exists(select 1 from public.beer_entries e where e.photo_path=name and e.is_public)));
create policy beer_photo_delete on storage.objects for delete to authenticated using(bucket_id='beer-photos' and split_part(name,'/',1)=(select auth.uid())::text);

commit;
